test("bob cannot read alice's invoice", async () => {
  const { body } = await request(app).post("/api/invoices").set(alice).send({ total: 10 });
  await request(app).get(`/api/invoices/${body.id}`).set(bob).expect(404);
  await request(app).get(`/api/invoices/${body.id}`).expect(401);
});
